#!/usr/bin/env node
/**
 * generate-readme-product-table.js
 *
 * Reads every registered artifact (artifacts/<slug>/.replit-artifact/artifact.toml)
 * and regenerates the canonical "Artifact inventory" table in README.md between
 * the marker comments:
 *
 *   <!-- BEGIN: artifact-inventory (auto-generated by scripts/generate-readme-product-table.js) -->
 *   ...table...
 *   <!-- END: artifact-inventory -->
 *
 * Usage:
 *   node scripts/generate-readme-product-table.js          # write table into README.md
 *   node scripts/generate-readme-product-table.js --check  # exit 1 if README is out of date
 */

import fs from "node:fs";
import path from "node:path";

const ROOT = process.cwd();
const ARTIFACTS_DIR = path.join(ROOT, "artifacts");
const README_PATH = path.join(ROOT, "README.md");
const BEGIN_MARKER =
  "<!-- BEGIN: artifact-inventory (auto-generated by scripts/generate-readme-product-table.js) -->";
const END_MARKER = "<!-- END: artifact-inventory -->";

const args = process.argv.slice(2);
const CHECK_MODE = args.includes("--check");

/**
 * Minimal TOML reader: extracts the top-level scalar fields we care about
 * (id, title, kind, previewPath). Keys inside [tables] are ignored, which is
 * what we want — every relevant field is at the top of artifact.toml.
 */
function readArtifactToml(filePath) {
  const raw = fs.readFileSync(filePath, "utf8");
  const fields = {};
  const lines = raw.split(/\r?\n/);
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    if (trimmed.startsWith("[")) break; // first table section ends top-level
    const m = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+?)\s*$/);
    if (!m) continue;
    let value = m[2];
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    fields[m[1]] = value;
  }
  return fields;
}

function loadArtifacts() {
  if (!fs.existsSync(ARTIFACTS_DIR)) return [];
  const slugs = fs
    .readdirSync(ARTIFACTS_DIR, { withFileTypes: true })
    .filter((d) => d.isDirectory())
    .map((d) => d.name);

  const artifacts = [];
  for (const slug of slugs) {
    const tomlPath = path.join(
      ARTIFACTS_DIR,
      slug,
      ".replit-artifact",
      "artifact.toml",
    );
    if (!fs.existsSync(tomlPath)) continue;
    const fields = readArtifactToml(tomlPath);
    artifacts.push({
      slug,
      id: fields.id || `artifacts/${slug}`,
      title: fields.title || slug,
      kind: fields.kind || "web",
      previewPath: fields.previewPath || `/${slug}/`,
      dirPath: `artifacts/${slug}/`,
    });
  }
  // Sort: corporate root ("/") first, then alphabetical by title.
  artifacts.sort((a, b) => {
    if (a.previewPath === "/" && b.previewPath !== "/") return -1;
    if (b.previewPath === "/" && a.previewPath !== "/") return 1;
    return a.title.localeCompare(b.title);
  });
  return artifacts;
}

function renderTable(artifacts) {
  const header =
    "| Artifact | Kind | Path | Preview |\n|----------|------|------|---------|";
  const rows = artifacts.map(
    (a) =>
      `| ${escapePipes(a.title)} | ${a.kind} | \`${a.dirPath}\` | \`${a.previewPath}\` |`,
  );
  return [header, ...rows].join("\n");
}

function escapePipes(s) {
  return String(s).replace(/\|/g, "\\|");
}

function buildBlock(artifacts) {
  const table = renderTable(artifacts);
  return `${BEGIN_MARKER}\n${table}\n${END_MARKER}`;
}

function ensureMarkers(readme) {
  const beginIdx = readme.indexOf(BEGIN_MARKER);
  const endIdx = readme.indexOf(END_MARKER);
  return beginIdx !== -1 && endIdx !== -1 && endIdx > beginIdx;
}

function replaceBlock(readme, newBlock) {
  const beginIdx = readme.indexOf(BEGIN_MARKER);
  const endIdx = readme.indexOf(END_MARKER) + END_MARKER.length;
  return readme.slice(0, beginIdx) + newBlock + readme.slice(endIdx);
}

function main() {
  if (!fs.existsSync(README_PATH)) {
    console.error(`ERROR: README not found at ${README_PATH}`);
    process.exit(1);
  }

  const artifacts = loadArtifacts();
  if (artifacts.length === 0) {
    console.error(
      "ERROR: no artifact.toml files found under artifacts/*/.replit-artifact/",
    );
    process.exit(1);
  }

  const readme = fs.readFileSync(README_PATH, "utf8");

  if (!ensureMarkers(readme)) {
    console.error(
      `ERROR: README.md is missing the artifact-inventory markers.\n` +
        `Insert the following block where the inventory table should live:\n\n` +
        `${BEGIN_MARKER}\n${END_MARKER}\n`,
    );
    process.exit(1);
  }

  const newBlock = buildBlock(artifacts);
  const updated = replaceBlock(readme, newBlock);

  if (CHECK_MODE) {
    if (updated !== readme) {
      console.error(
        "README.md artifact inventory is out of date.\n" +
          "Run: pnpm readme:generate\n",
      );
      process.exit(1);
    }
    console.log(
      `README.md artifact inventory is up to date (${artifacts.length} artifacts).`,
    );
    return;
  }

  if (updated === readme) {
    console.log(
      `README.md artifact inventory already current (${artifacts.length} artifacts).`,
    );
    return;
  }

  fs.writeFileSync(README_PATH, updated);
  console.log(
    `Updated README.md artifact inventory (${artifacts.length} artifacts).`,
  );
}

main();
